const socket=io(),palette=['amber','violet','sky','rose'];let me=null,roomId=null,people=[],typingTimer;const $=s=>document.querySelector(s),list=$('#conversationList'),area=$('#messageArea'),input=$('#messageInput'),toast=$('#toast'),dialog=$('#roomDialog'),sidebar=$('#sidebar');
const escapeHtml=value=>{const el=document.createElement('div');el.textContent=value;return el.innerHTML};const styleFor=name=>palette[(name.charCodeAt(0)||0)%palette.length];const avatar=(name,small=false)=>`<div class="avatar avatar-${styleFor(name)} ${small?'small':''}">${escapeHtml(name.slice(0,1).toUpperCase())}</div>`;
function notify(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}function renderPeople(){list.innerHTML=people.length?people.map((person,index)=>`<div class="conversation ${person===me?'active':''}">${avatar(person)}<span><strong>${escapeHtml(person)}${person===me?' (you)':''}</strong><p>${person===me?'You are connected':'Online now'}</p></span><time>${index===0?'●':''}</time></div>`).join(''):'<p class="empty">No one is in this room yet.</p>'}function updateRoom(){let count=people.length;$('#chatTitle').textContent=roomId?`Room ${roomId}`:'Welcome to M - Connect';$('#headerAvatar').textContent=roomId?'#':'?';$('#chatPresence').innerHTML=roomId?`<i></i> ${count} ${count===1?'person':'people'} online`:'<i></i> Connect to a room to chat';$('#profileName').textContent=me||'Not connected';$('#profileInitial').textContent=me?me[0].toUpperCase():'?';$('#profileStatus').textContent=roomId?`Room ${roomId}`:'Choose a room';renderPeople()}function resetMessages(){area.innerHTML='<p class="day-marker">LIVE CHAT</p>'}function addMessage(message){let mine=message.name===me,article=document.createElement('article');article.className=`message ${mine?'me':'them'}`;article.innerHTML=`${avatar(message.name,true)}<div class="bubble">${mine?'':`<b>${escapeHtml(message.name)}</b><br>`}${escapeHtml(message.text)}<time class="time">${escapeHtml(message.timestamp)}${mine?' · ✓✓':''}</time></div>`;area.append(article);area.scrollTop=area.scrollHeight}function showSystem(text){let marker=document.createElement('p');marker.className='day-marker';marker.textContent=text;area.append(marker);area.scrollTop=area.scrollHeight}
function joinRoom(create=false){let name=$('#nameInput').value.trim(),code=$('#roomInput').value.trim();if(!name)return notify('Please enter your name.');socket.emit(create?'create-room':'join-room',{name,roomId:code},reply=>{if(!reply?.ok)return notify(reply?.error||'Unable to join room.');me=name;roomId=reply.roomId;dialog.close();resetMessages();updateRoom();notify(`Connected to room ${roomId}`)})}function send(){let text=input.value.trim();if(!text||!roomId)return;socket.emit('send-message',text);input.value='';socket.emit('stop-typing')}
$('#composer').onsubmit=e=>{e.preventDefault();send()};input.oninput=()=>{if(!roomId)return;socket.emit('typing');clearTimeout(typingTimer);typingTimer=setTimeout(()=>socket.emit('stop-typing'),900)};$('#search').oninput=e=>{let filter=e.target.value.toLowerCase();list.querySelectorAll('.conversation').forEach(item=>item.hidden=!item.textContent.toLowerCase().includes(filter))};$('#mobileMenu').onclick=()=>sidebar.classList.toggle('open');$('#newChat').onclick=()=>{$('#roomInput').value='';dialog.showModal()};$('.emoji').onclick=()=>{input.value+=' 😊';input.focus()};$('.attach').onclick=()=>notify('File sharing is not available yet.');$('#inviteButton').onclick=async()=>{if(!roomId)return dialog.showModal();try{await navigator.clipboard.writeText(roomId);notify(`Room code ${roomId} copied.`)}catch{notify(`Share this room code: ${roomId}`)}};$('#roomForm').onsubmit=e=>{e.preventDefault();joinRoom(!$('#roomInput').value.trim())};
socket.on('room-history',data=>{people=data.people;resetMessages();data.messages.forEach(addMessage);updateRoom()});socket.on('room-users',data=>{people=data.people;updateRoom()});socket.on('receive-message',addMessage);socket.on('system-message',showSystem);socket.on('user-typing',text=>{let typing=$('#typing');typing.textContent=text;typing.classList.toggle('show',Boolean(text))});socket.on('disconnect',()=>{if(roomId)notify('Connection lost. Reconnecting…')});socket.on('connect',()=>{if(me&&roomId)socket.emit('join-room',{name:me,roomId},reply=>{if(!reply?.ok)notify('Could not restore the room connection.')})});dialog.showModal();
